// Roadmap 0.42 E1: incident forensics. Every input is built here from public material: the
// receiver logs are generated by the open engine's NMEA training generator from its five
// library scenarios (tests/fixtures/forensics/training, copied from the open repository's
// scenarios/training), whose instructor logs say what was injected when; the AIS and ADS-B
// files are synthetic, in the open engine's documented CSV formats, and the area sample is
// the open repository's synthetic interference-map input (tests/fixtures/forensics). No
// TEXBAT or JammerTest data is used or committed.
//
// The training scenarios are a development set: the method was exercised on them while it
// was written. They are not the labelled set of roadmap V2, and passing here is not a
// detection-rate claim.

use std::path::{Path, PathBuf};

use kshana::receiver_trust::LogFormat;
use kshana_pro::forensics::bundle::{self, BundleRequest, ReviewInput};
use kshana_pro::forensics::detect::{analyse, ForensicReport};
use kshana_pro::forensics::inputs::{iso, parse_utc};
use kshana_pro::forensics::{IncidentScenario, Variant, LABEL, VALIDATION_STATUS};
use kshana_pro::license::public_key_for;
use kshana_pro::signed_dossier;

const FIX: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/forensics");
const ISSUER: [u8; 32] = [0x51; 32];
const REVIEWER: [u8; 32] = [0x52; 32];
const UTC: &str = "2026-11-15T12:00:00Z";

fn tmp(name: &str) -> PathBuf {
    let d = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("forensics-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&d);
    std::fs::create_dir_all(&d).unwrap();
    d
}

fn training(name: &str) -> String {
    std::fs::read_to_string(format!("{FIX}/training/{name}.toml")).unwrap()
}

/// Generate a training stream; returns (NMEA text, start Unix s, duration s).
fn stream(toml_text: &str) -> (String, f64, f64) {
    let g = kshana::nmea_synth::generate_from_toml(toml_text, None).unwrap();
    let v: toml::Value = toml::from_str(toml_text).unwrap();
    let t0 = parse_utc(v["scenario"]["start_utc"].as_str().unwrap()).unwrap();
    let dur = v["scenario"]["duration_s"].as_integer().unwrap() as f64;
    (g.nmea_text(), t0, dur)
}

fn receiver_only(name: &str, dir: &Path) -> (IncidentScenario, f64) {
    let (nmea, t0, dur) = stream(&training(name));
    std::fs::write(dir.join("bridge.nmea"), nmea).unwrap();
    let inc = format!(
        "kind = \"pro-incident-forensics\"\n[incident]\nid = \"T-{name}\"\ntitle = \"{name}\"\n\
         start_utc = \"{}\"\nend_utc = \"{}\"\n\
         [[receiver]]\nlabel = \"Bridge GNSS\"\npath = \"bridge.nmea\"\nformat = \"nmea\"\nplatform = \"vessel\"\n",
        iso(t0 + 200.0),
        iso(t0 + dur),
    );
    std::fs::write(dir.join("incident.toml"), inc).unwrap();
    (
        IncidentScenario::from_file(&dir.join("incident.toml")).unwrap(),
        t0,
    )
}

fn t(r: &str) -> f64 {
    parse_utc(r).unwrap()
}

/// The development set: each library scenario's injected events are found, with the onset
/// after the injection starts and before its ramp ends plus 60 s; the natural degradation
/// in the fjord is not attributed to interference.
#[test]
fn the_training_scenarios_are_attributed_as_injected() {
    // (category, injected at s, ramp s)
    type Injected = (&'static str, f64, f64);
    let cases: &[(&str, &[Injected])] = &[
        ("open-sea-jamming", &[("jamming", 300.0, 90.0)]),
        ("coastal-drag-off", &[("spoofing", 420.0, 360.0)]),
        ("port-approach-time-spoof", &[("spoofing", 300.0, 120.0)]),
        ("combined-event", &[("jamming", 240.0, 45.0)]),
    ];
    for (name, events) in cases {
        let d = tmp(name);
        let (scn, t0) = receiver_only(name, &d);
        let r = analyse(&scn, None).unwrap();
        for (cat, start, ramp) in events.iter() {
            let f = r
                .findings
                .iter()
                .find(|f| f.category == *cat || f.category == "jamming-and-spoofing")
                .unwrap_or_else(|| panic!("{name}: no {cat} finding: {}", r.verdict.sentence));
            let onset = t(&f.onset.latest_utc) - t0;
            assert!(
                onset >= *start && onset <= start + ramp + 60.0,
                "{name}: {cat} onset at {onset} s, injected at {start} s"
            );
            assert!(t(&f.onset.earliest_utc) <= t(&f.onset.latest_utc));
            assert_eq!(f.data_class, "measured");
            assert_eq!(f.inference_class, "modelled");
            // One receiver only: never high confidence.
            assert_ne!(f.confidence.level, "high", "{name}");
            assert!(!f.supported);
        }
    }
    // The combined event also carries the drag-off and time spoofing (500 s to 1200 s).
    let d = tmp("combined-spoof");
    let (scn, t0) = receiver_only("combined-event", &d);
    let r = analyse(&scn, None).unwrap();
    assert_eq!(r.verdict.spoofing.status, "indicated");
    assert!(r.findings.iter().any(|f| {
        (f.category == "spoofing" || f.category == "jamming-and-spoofing")
            && t(&f.onset.latest_utc) - t0 < 1200.0
            && t(&f.end.earliest_utc) - t0 > 500.0
    }));
    // The fjord: obstruction, not interference.
    let d = tmp("fjord");
    let (scn, _) = receiver_only("fjord-natural-degradation", &d);
    let r = analyse(&scn, None).unwrap();
    assert_eq!(
        r.verdict.jamming.status, "not-indicated",
        "{}",
        r.verdict.sentence
    );
    assert_eq!(r.verdict.spoofing.status, "not-indicated");
    assert!(r
        .findings
        .iter()
        .all(|f| f.category == "degradation-not-attributed" && f.confidence.level == "low"));
}

/// AIS rows from the receiver's own fixes every 10 s (a fix-less epoch sends nothing).
fn ais_from_fixes(nmea: &str, id: &str) -> Vec<String> {
    let tl = kshana::receiver_trust::ingest::read_log(LogFormat::Nmea, nmea.as_bytes()).unwrap();
    let t0 = parse_utc(tl.start_label.as_deref().unwrap()).unwrap();
    tl.epochs
        .iter()
        .filter(|e| (e.t_s as i64) % 10 == 0)
        .filter_map(|e| {
            e.fix.map(|f| {
                format!(
                    "{},{id},{:.5},{:.5},14",
                    iso(t0 + e.t_s),
                    f.lat_deg,
                    f.lon_deg
                )
            })
        })
        .collect()
}

/// A coherent synthetic incident: the open-sea jamming scenario as the subject's bridge log,
/// a second vessel nearby with its own log, AIS for the subject and five other vessels, and
/// ADS-B from six aircraft of which four lose integrity over the area during the jamming.
fn jamming_incident(dir: &Path, variant: Variant, custody: bool) -> IncidentScenario {
    let base = training("open-sea-jamming");
    let (nmea, t0, _) = stream(&base);
    std::fs::write(dir.join("bridge.nmea"), &nmea).unwrap();
    let other = base
        .replace("seed = 11", "seed = 12")
        .replace(
            "lat_deg = 55.20\nlon_deg = 2.50",
            "lat_deg = 55.30\nlon_deg = 2.70",
        )
        .replace("start_s = 300", "start_s = 320");
    let (nmea2, _, _) = stream(&other);
    std::fs::write(dir.join("other-vessel.nmea"), &nmea2).unwrap();

    let mut ais = vec!["timestamp,vessel_id,lat,lon,sog_kn".to_string()];
    ais.extend(ais_from_fixes(&nmea, "SUBJECT-1"));
    for v in 0..5 {
        for k in 0..40 {
            let tt = t0 + 30.0 * k as f64;
            ais.push(format!(
                "{},NEIGH-{v},{:.5},{:.5},11",
                iso(tt),
                55.10 + 0.08 * v as f64,
                2.30 + 0.0015 * k as f64
            ));
        }
    }
    std::fs::write(dir.join("ais.csv"), ais.join("\n") + "\n").unwrap();

    let mut adsb =
        vec!["timestamp,aircraft_id,lat,lon,alt_baro_ft,nic,nacp,source_type".to_string()];
    for a in 0..6 {
        let lat = if a < 4 { 55.15 + 0.1 * a as f64 } else { 57.5 };
        for k in 0..40 {
            let tt = t0 + 30.0 * k as f64;
            let lon = 2.0 + 0.045 * k as f64;
            let hit = a < 4 && (360.0..=720.0).contains(&(tt - t0));
            let (nic, nacp) = if hit { (0, 0) } else { (8, 9) };
            adsb.push(format!(
                "{},AC-{a},{lat:.4},{lon:.4},35000,{nic},{nacp},adsb_icao",
                iso(tt)
            ));
        }
    }
    std::fs::write(dir.join("adsb.csv"), adsb.join("\n") + "\n").unwrap();

    let custody_toml = if custody {
        ["Bridge GNSS", "Other vessel GNSS", "AIS feed", "ADS-B feed"]
            .iter()
            .map(|l| {
                format!(
                    "[[custody]]\ninput = \"{l}\"\nreceived_from = \"Operator (synthetic test)\"\n\
                     received_utc = \"2026-05-15T09:00:00Z\"\nmethod = \"secure upload\"\n"
                )
            })
            .collect::<String>()
    } else {
        String::new()
    };
    let inc = format!(
        "kind = \"pro-incident-forensics\"\nvariant = \"{}\"\n\
[incident]\nid = \"SAMPLE-E1-0001\"\ntitle = \"Synthetic open-sea jamming (training scenario)\"\n\
subject = \"vessel\"\nsubject_id = \"SUBJECT-1\"\nstart_utc = \"{}\"\nend_utc = \"{}\"\n\
reported = \"Master reports GPS lost on the bridge for several minutes.\"\nrequested_by = \"Synthetic test\"\n\
[incident.area]\nlat_min = 55.0\nlat_max = 55.7\nlon_min = 2.2\nlon_max = 3.9\n\
[[receiver]]\nlabel = \"Bridge GNSS\"\npath = \"bridge.nmea\"\nformat = \"nmea\"\nrole = \"subject\"\nplatform = \"vessel\"\n\
[[receiver]]\nlabel = \"Other vessel GNSS\"\npath = \"other-vessel.nmea\"\nformat = \"nmea\"\nrole = \"other\"\nplatform = \"vessel\"\n\
[[ais]]\nlabel = \"AIS feed\"\npath = \"ais.csv\"\n\
[[adsb]]\nlabel = \"ADS-B feed\"\npath = \"adsb.csv\"\n\
[[statement]]\nsource = \"Master (as reported)\"\nutc = \"{}\"\ntext = \"GPS lost on the bridge\"\n{custody_toml}",
        variant.as_str(),
        iso(t0 + 200.0),
        iso(t0 + 1200.0),
        iso(t0 + 380.0),
    );
    std::fs::write(dir.join("incident.toml"), inc).unwrap();
    IncidentScenario::from_file(&dir.join("incident.toml")).unwrap()
}

fn build(scn: &IncidentScenario, out: &Path) -> ForensicReport {
    bundle::build_bundle(&BundleRequest {
        scenario: scn,
        out,
        utc: UTC,
        seed: &ISSUER,
        signer: "Ashforde OÜ (test issuer)",
    })
    .unwrap()
    .report
}

#[test]
fn a_corroborated_incident_gives_high_confidence_findings_with_evidence_classes() {
    let d = tmp("incident");
    let scn = jamming_incident(&d, Variant::Standard, false);
    let r = analyse(&scn, Some(UTC)).unwrap();
    assert_eq!(r.label, LABEL);
    assert_eq!(r.validation_status, VALIDATION_STATUS);
    assert_eq!(r.status, "final");
    assert_eq!(
        r.verdict.jamming.status, "indicated",
        "{}",
        r.verdict.sentence
    );
    assert_eq!(r.verdict.jamming.confidence, Some("high"));
    // Receiver findings (measured) and the ADS-B integrity drop (reported) corroborate.
    let rx: Vec<_> = r
        .findings
        .iter()
        .filter(|f| f.source_kind == "receiver")
        .collect();
    let ad: Vec<_> = r
        .findings
        .iter()
        .filter(|f| f.source_kind == "adsb")
        .collect();
    assert_eq!(
        rx.len(),
        2,
        "{:?}",
        r.findings.iter().map(|f| &f.statement).collect::<Vec<_>>()
    );
    assert_eq!(ad.len(), 1);
    assert_eq!(ad[0].category, "jamming");
    assert_eq!(ad[0].data_class, "reported");
    assert_eq!(ad[0].magnitude["aircraft_flagged"], 4.0);
    for f in rx.iter().chain(ad.iter()) {
        assert_eq!(
            f.confidence.level, "high",
            "{}: {:?}",
            f.id, f.confidence.reasons
        );
        assert!(f.supported);
        assert!(!f.corroborated_by.is_empty());
        assert!(f.evidence.iter().any(|e| e.class == "modelled"));
        assert!(f
            .evidence
            .iter()
            .any(|e| e.class == f.data_class && e.input_sha256.is_some()));
    }
    let subject = rx.iter().find(|f| f.source == "Bridge GNSS").unwrap();
    assert!(subject.about_subject);
    let pos = subject.position_at_onset.as_ref().unwrap();
    assert_eq!(pos.class, "measured");
    assert!((pos.lat - 55.2).abs() < 0.2 && (pos.lon - 2.6).abs() < 0.4);
    // Every input hashed, with its class and coverage.
    assert_eq!(r.inputs.len(), 4);
    for i in &r.inputs {
        assert_eq!(i.sha256.len(), 64);
        assert!(i.window_coverage.unwrap() > 0.9, "{}", i.label);
    }
    assert_eq!(
        r.inputs
            .iter()
            .filter(|i| i.data_class == "measured")
            .count(),
        2
    );
    // The affected area is modelled from the observers, with no emitter claim.
    assert_eq!(r.area.class, "modelled");
    assert!(r.area.affected_observers >= 6);
    assert!(r.area.radius_m.unwrap() > 5000.0);
    assert!(r.area.note.contains("not an emitter location"));
    // The subject's tracks (receiver: measured; AIS: reported) and the AIS view of the area.
    assert!(r
        .tracks
        .iter()
        .any(|t| t.class == "measured" && t.points.iter().any(|p| p.flagged)));
    assert!(r.tracks.iter().any(|t| t.class == "reported"));
    let ais = r.area_activity.iter().find(|a| a.source == "ais").unwrap();
    assert_eq!(ais.observed, 6);
    assert_eq!(ais.flagged_any, 0);
    // The timeline holds the window, the findings and the statement (reported).
    assert!(r
        .timeline
        .iter()
        .any(|e| e.kind == "statement" && e.class == "reported"));
    assert!(r.timeline.windows(2).all(|w| t(&w[0].utc) <= t(&w[1].utc)));
    // Standard: no review needed.
    assert!(!r.expert_review.required);
    assert_eq!(r.expert_review.status, "not-required");
}

#[test]
fn the_open_sample_area_shows_ais_and_adsb_anomalies() {
    let d = tmp("area");
    std::fs::copy(format!("{FIX}/ais.csv"), d.join("ais.csv")).unwrap();
    std::fs::copy(format!("{FIX}/adsb.csv"), d.join("adsb.csv")).unwrap();
    let inc = "kind = \"pro-incident-forensics\"\n[incident]\nid = \"SAMPLE-AREA\"\ntitle = \"Synthetic mid-Atlantic area\"\n\
subject = \"area\"\nstart_utc = \"2026-03-01T09:30:00Z\"\nend_utc = \"2026-03-01T14:30:00Z\"\n\
[[ais]]\nlabel = \"AIS sample\"\npath = \"ais.csv\"\n[[adsb]]\nlabel = \"ADS-B sample\"\npath = \"adsb.csv\"\n";
    std::fs::write(d.join("incident.toml"), inc).unwrap();
    let scn = IncidentScenario::from_file(&d.join("incident.toml")).unwrap();
    let r = analyse(&scn, Some(UTC)).unwrap();
    let ind = |n: &str| r.findings.iter().find(|f| f.indicators == [n]);
    let circ = ind("ais-circular-track").expect("circles");
    assert_eq!(circ.magnitude["vessels_flagged"], 6.0);
    assert_eq!(circ.category, "spoofing");
    let speed = ind("ais-implausible-speed").expect("speed");
    assert_eq!(speed.magnitude["vessels_flagged"], 2.0);
    let adsb = ind("adsb-integrity-drop").expect("integrity");
    assert_eq!(adsb.magnitude["aircraft_flagged"], 7.0);
    // Ordinary traffic is not flagged by the jump detector.
    assert!(ind("ais-position-jump").is_none());
    let a = r.area_activity.iter().find(|a| a.source == "adsb").unwrap();
    // SYN-B never reported good integrity: unassessed, not flagged.
    assert_eq!(a.unassessed, Some(7));
    // AIS spoofing-like and ADS-B jamming-like do not corroborate each other.
    assert!(r.findings.iter().all(|f| f.confidence.level != "high"));
}

#[test]
fn the_bundle_is_signed_verifies_free_and_reproduces_from_its_recipe() {
    let d = tmp("bundle");
    let scn = jamming_incident(&d, Variant::Standard, false);
    let out = d.join("out");
    let r = build(&scn, &out);
    for f in [
        "report.json",
        "report.html",
        "report.pdf",
        "findings.csv",
        "timeline.csv",
        "timeline.svg",
        "area.geojson",
        "tracks.geojson",
        "recipe.toml",
        "inputs/bridge.nmea",
        "inputs/ais.csv",
        "signature.json",
    ] {
        assert!(out.join(f).is_file(), "{f}");
    }
    assert!(std::fs::read(out.join("report.pdf"))
        .unwrap()
        .starts_with(b"%PDF"));
    let html = std::fs::read_to_string(out.join("report.html")).unwrap();
    for s in [
        "1. What happened",
        "4. How confident",
        "5. What it rests on",
        "6. How to reproduce it",
        "MODELLED",
        "REPORTED",
        "MEASURED",
    ] {
        assert!(html.contains(s), "{s}");
    }
    // Two open-engine evidence packs, one per receiver log.
    assert_eq!(
        r.checklist.iter().find(|c| c.id == "C9").unwrap().result,
        "pass"
    );

    // Free verification: the bundle signature, the inputs, the open evidence packs.
    let pk = public_key_for(&ISSUER);
    let v = bundle::verify_bundle(&out, &[pk], &[]).unwrap();
    assert!(v.passed(), "{:?}", v.problems);
    assert_eq!(v.inputs_checked, 4);
    assert_eq!(v.evidence_packs_ok, 2);
    assert!(!v.claim_grade_complete());
    // The generic dossier verifier agrees (kshana-pro dossier verify).
    assert!(signed_dossier::verify(&out, &[pk]).unwrap().passed());
    // An unpinned key verifies the bytes but is not trusted.
    assert!(!bundle::verify_bundle(&out, &[], &[]).unwrap().passed());

    // Reproduce from the recipe, inside the bundle: report.json and the data files are
    // byte-identical (the PDF differs only in its trailer /ID).
    let again = IncidentScenario::from_file(&out.join("recipe.toml")).unwrap();
    let out2 = d.join("again");
    build(&again, &out2);
    for f in [
        "report.json",
        "report.html",
        "findings.csv",
        "timeline.csv",
        "timeline.svg",
        "area.geojson",
        "tracks.geojson",
        "recipe.toml",
        "inputs/bridge.nmea",
        "evidence/1-bridge-gnss/manifest.json",
        "evidence/1-bridge-gnss/epochs.json",
    ] {
        assert_eq!(
            std::fs::read(out.join(f)).unwrap(),
            std::fs::read(out2.join(f)).unwrap(),
            "{f} differs on re-run"
        );
    }

    // Tampering is caught: an input byte, the report, a removed file.
    let mut b = std::fs::read(out.join("inputs/ais.csv")).unwrap();
    b[40] ^= 1;
    std::fs::write(out.join("inputs/ais.csv"), &b).unwrap();
    let v = bundle::verify_bundle(&out, &[pk], &[]).unwrap();
    assert!(!v.passed());
    assert!(
        v.problems.iter().any(|p| p.contains("inputs/ais.csv")),
        "{:?}",
        v.problems
    );
    b[40] ^= 1;
    std::fs::write(out.join("inputs/ais.csv"), &b).unwrap();
    assert!(bundle::verify_bundle(&out, &[pk], &[]).unwrap().passed());
    let rep = std::fs::read_to_string(out.join("report.json")).unwrap();
    std::fs::write(
        out.join("report.json"),
        rep.replace("\"high\"", "\"medium\""),
    )
    .unwrap();
    assert!(!bundle::verify_bundle(&out, &[pk], &[]).unwrap().passed());
    std::fs::write(out.join("report.json"), &rep).unwrap();
    std::fs::remove_file(out.join("evidence/2-other-vessel-gnss/manifest.sig")).unwrap();
    assert!(!bundle::verify_bundle(&out, &[pk], &[]).unwrap().passed());
    // A second run into a non-empty folder is refused.
    assert!(bundle::build_bundle(&BundleRequest {
        scenario: &scn,
        out: &out,
        utc: UTC,
        seed: &ISSUER,
        signer: "x",
    })
    .is_err());
}

fn review<'a>(statement: &'a str, decision: &'a str) -> ReviewInput<'a> {
    ReviewInput {
        reviewer_name: "A. Reviewer (synthetic test identity)",
        qualification: "Test fixture: no real qualification",
        organisation: "Test fixture",
        independence_statement: "Test fixture: no relation to the parties",
        decision,
        statement,
        reviewed_utc: "2026-11-16T10:00:00Z",
        seed: &REVIEWER,
    }
}

#[test]
fn claim_grade_needs_its_checklist_and_a_signed_review() {
    // Without chain-of-custody records the claim-grade checklist is not met.
    let d = tmp("claim-no-custody");
    let scn = jamming_incident(&d, Variant::ClaimGrade, false);
    let out = d.join("out");
    let r = build(&scn, &out);
    assert_eq!(r.status, "claim-grade-checklist-not-met");
    assert_eq!(
        r.checklist.iter().find(|c| c.id == "C5").unwrap().result,
        "fail"
    );
    assert_eq!(r.expert_review.status, "not-eligible");
    assert!(bundle::add_review(&out, &review("ok", "concur")).is_err());

    // With them it awaits review; every review field is empty, nothing is filled in.
    let d = tmp("claim");
    let scn = jamming_incident(&d, Variant::ClaimGrade, true);
    let out = d.join("out");
    let r = build(&scn, &out);
    assert_eq!(r.status, "awaiting-expert-review", "{:?}", r.checklist);
    let e = &r.expert_review;
    assert!(e.required);
    assert_eq!(e.status, "awaiting-review");
    assert!(e.reviewer_name.is_none() && e.qualification.is_none() && e.decision.is_none());
    assert!(e.statement.is_none() && e.reviewed_utc.is_none() && e.organisation.is_none());
    for c in ["C3", "C4", "C5", "C6", "C7", "C8", "C9"] {
        assert_eq!(
            r.checklist.iter().find(|x| x.id == c).unwrap().result,
            "pass",
            "{c}"
        );
    }
    assert_eq!(
        r.checklist.iter().find(|x| x.id == "C10").unwrap().result,
        "pending"
    );
    let pk = public_key_for(&ISSUER);
    let rk = public_key_for(&REVIEWER);
    let v = bundle::verify_bundle(&out, &[pk], &[]).unwrap();
    assert!(v.passed() && !v.claim_grade_complete());

    // A bad decision or an empty field is refused.
    assert!(bundle::add_review(&out, &review("ok", "maybe")).is_err());
    assert!(bundle::add_review(&out, &review("  ", "concur")).is_err());
    // The reviewer signs; until the issuer re-signs, the bundle shows an added file.
    bundle::add_review(
        &out,
        &review("The findings follow from the data supplied.", "concur"),
    )
    .unwrap();
    assert!(bundle::add_review(&out, &review("again", "concur")).is_err());
    let v = bundle::verify_bundle(&out, &[pk], &[rk]).unwrap();
    assert!(!v.passed());
    assert_eq!(v.review_ok, Some(true));
    signed_dossier::sign(
        &out,
        &ISSUER,
        "Ashforde OÜ (test issuer)",
        "2026-11-16T11:00:00Z",
    )
    .unwrap();
    let v = bundle::verify_bundle(&out, &[pk], &[rk]).unwrap();
    assert!(v.passed(), "{:?}", v.problems);
    assert!(v.claim_grade_complete());
    assert_eq!(v.review_decision.as_deref(), Some("concur"));
    // Another pinned reviewer key: the review is not trusted.
    let v = bundle::verify_bundle(&out, &[pk], &[public_key_for(&[9; 32])]).unwrap();
    assert!(!v.passed() && !v.claim_grade_complete());
    // A review moved onto another report (report.json changed and re-signed) fails.
    let rep = std::fs::read_to_string(out.join("report.json")).unwrap();
    std::fs::write(
        out.join("report.json"),
        rep.replace("SAMPLE-E1-0001", "SAMPLE-E1-0002"),
    )
    .unwrap();
    signed_dossier::sign(&out, &ISSUER, "x", "2026-11-16T12:00:00Z").unwrap();
    let v = bundle::verify_bundle(&out, &[pk], &[rk]).unwrap();
    assert_eq!(v.review_ok, Some(false));
    assert!(!v.passed());
}

#[test]
fn bad_incidents_are_refused_with_a_reason() {
    let d = tmp("bad");
    std::fs::write(d.join("a.csv"), "timestamp,vessel_id,lat,lon\n").unwrap();
    let head = "kind = \"pro-incident-forensics\"\n[incident]\nid = \"X\"\ntitle = \"x\"\n";
    let cases = [
        (format!("{head}start_utc = \"2026-01-01T01:00:00Z\"\nend_utc = \"2026-01-01T00:00:00Z\"\n[[ais]]\nlabel = \"a\"\npath = \"a.csv\"\n"), "after"),
        (format!("{head}start_utc = \"yesterday\"\nend_utc = \"2026-01-01T00:00:00Z\"\n"), "ISO-8601"),
        (format!("{head}start_utc = \"2026-01-01T00:00:00Z\"\nend_utc = \"2026-01-01T01:00:00Z\"\n"), "no data file"),
        (format!("{head}start_utc = \"2026-01-01T00:00:00Z\"\nend_utc = \"2026-01-01T01:00:00Z\"\n[[ais]]\nlabel = \"a\"\npath = \"missing.csv\"\n"), "missing.csv"),
        (format!("{head}start_utc = \"2026-01-01T00:00:00Z\"\nend_utc = \"2026-01-01T01:00:00Z\"\n[[ais]]\nlabel = \"a\"\npath = \"a.csv\"\n[[adsb]]\nlabel = \"a\"\npath = \"a.csv\"\n"), "twice"),
    ];
    for (src, want) in cases {
        std::fs::write(d.join("i.toml"), &src).unwrap();
        let e = IncidentScenario::from_file(&d.join("i.toml"))
            .and_then(|s| analyse(&s, None))
            .unwrap_err()
            .to_string();
        assert!(e.contains(want), "{want}: {e}");
    }
    assert!(IncidentScenario::parse(
        "kind = \"pro-twin\"\n[incident]\nid=\"x\"\ntitle=\"x\"\nstart_utc=\"a\"\nend_utc=\"b\"\n"
    )
    .is_err());
    assert!(IncidentScenario::parse(&format!(
        "{head}start_utc=\"a\"\nend_utc=\"b\"\nunknown = 1\n"
    ))
    .is_err());
}

#[test]
fn the_command_line_refuses_without_a_licence_runs_with_dev_and_verifies_free() {
    let bin = env!("CARGO_BIN_EXE_kshana-pro");
    let d = tmp("cli");
    jamming_incident(&d, Variant::Standard, false);
    let key = d.join("issuer.key");
    std::fs::write(&key, format!("private_key={}\n", hex::encode(ISSUER))).unwrap();
    let run = |args: &[&str]| {
        let o = std::process::Command::new(bin)
            .args(args)
            .env("KSHANA_PRO_HOME", d.join("home"))
            .output()
            .unwrap();
        (
            o.status.code(),
            String::from_utf8_lossy(&o.stdout).to_string() + &String::from_utf8_lossy(&o.stderr),
        )
    };
    let inc = d.join("incident.toml");
    let out = d.join("out");
    let (i, o, k) = (
        inc.to_str().unwrap(),
        out.to_str().unwrap(),
        key.to_str().unwrap(),
    );
    // No licence: refused (Evaluation tier), nothing written.
    let (code, text) = run(&[
        "forensics",
        "run",
        i,
        "--out",
        o,
        "--key-file",
        k,
        "--signer",
        "T",
    ]);
    assert_ne!(code, Some(0), "{text}");
    assert!(text.contains("requires the 'pro' tier"), "{text}");
    assert!(!out.exists());
    // Debug build, --dev: written and signed; --sample marks the pages.
    let (code, text) = run(&[
        "forensics",
        "run",
        i,
        "--out",
        o,
        "--key-file",
        k,
        "--signer",
        "T",
        "--utc",
        UTC,
        "--dev",
        "--sample",
    ]);
    assert_eq!(code, Some(0), "{text}");
    assert!(text.contains("Jamming is indicated"), "{text}");
    assert!(std::fs::read_to_string(out.join("report.html"))
        .unwrap()
        .contains("SAMPLE"));
    // Verification needs no licence.
    let pk = hex::encode(public_key_for(&ISSUER));
    let (code, text) = run(&["forensics", "verify", o, "--trust", &pk]);
    assert_eq!(code, Some(0), "{text}");
    assert!(
        text.contains("VERIFIED") && text.contains("2 open evidence pack(s) verify"),
        "{text}"
    );
    let (code, text) = run(&["dossier", "verify", o, "--trust", &pk]);
    assert_eq!(code, Some(0), "{text}");
    let (code, _) = run(&["forensics", "verify", o]);
    assert_ne!(code, Some(0));
    // Claim-grade without custody: written, exit 3.
    let out3 = d.join("out3");
    let (code, text) = run(&[
        "forensics",
        "run",
        i,
        "--out",
        out3.to_str().unwrap(),
        "--key-file",
        k,
        "--signer",
        "T",
        "--variant",
        "claim-grade",
        "--dev",
    ]);
    assert_eq!(code, Some(3), "{text}");
    assert!(out3.join("report.json").exists());
    // The release pipeline's payload files.
    let pay = d.join("payload");
    let (code, text) = run(&["forensics", "pack-payload", pay.to_str().unwrap()]);
    assert_eq!(code, Some(0), "{text}");
    assert!(pay.join("forensics/method.json").exists());
}
